"""Controller controller -- generated by plugin_authoring. See context.md for this plugin's iteration history."""

from __future__ import annotations

import json
import os
import threading
import udi_interface

LOGGER = udi_interface.LOGGER


class Controller(udi_interface.Node):
    id = 'controller'
    drivers = [{'driver': 'ST', 'value': 0, 'uom': 25, 'name': 'Status'}]
    def __init__(self, polyglot, primary='ctl', address='ctl', name='Ocelot Controller'):
        super().__init__(polyglot, primary, address, name)
        self.poly = polyglot
        self.persist_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "persist")
        os.makedirs(self.persist_dir, exist_ok=True)
        # Synchronization for __start()'s wait-for-configDone gate (see __configDoneHandler).
        self.configDone = threading.Condition()
        self.configDoneAlready = False
        self.poly.setCustomParamsDoc('<h2>Ocelot plugin settings</h2>\n<p>After changing a setting, the plugin reconnects and re-scans automatically. Look for a notice banner at the top of this page if something needs attention.</p>\n\n<h3>IPAddress (required)</h3>\n<p>The IPv4 address (for example <code>192.168.0.70</code>) or host name of the serial-to-Ethernet adapter (Moxa, Lantronix, ser2net, ...) connected to the Ocelot\'s RS-232 port. Enter only the address: no <code>socket://</code> prefix and no <code>:port</code> part.</p>\n\n<h3>IPPort (required)</h3>\n<p>The adapter\'s TCP port for that serial port, a whole number from 1 to 65535 (for example <code>3001</code>). It is the "TCP server" port configured on the adapter, which must be in raw TCP mode (not Telnet or RFC 2217).</p>\n<p>The plugin joins these into <code>socket://IPAddress:IPPort</code>. If either value is missing or not valid, a banner explains why and nothing is opened.</p>\n<p>The speed and format of the serial link are set on the adapter, and must match the Ocelot\'s (C-Max\'s Comms Setup screen shows them).</p>\n<p>Important: while this plugin is connected, nothing else (such as C-Max) can use the adapter\'s connection to the Ocelot. Adapters usually accept one TCP client at a time.</p>\n\n<h3>InvertInputs</h3>\n<p><code>false</code> (default) shows an input bit of 1 as On. Set to <code>true</code> if your sensors are wired so the bit meaning is the other way round. The protocol document does not say which polarity a closed contact has, so test with a real sensor.</p>\n\n<h3>Removed settings</h3>\n<p><b>Port</b> (removed in 1.6.0), <b>X10Devices</b> (removed in 1.7.0 together with X-10 support) and <b>Baud</b> (removed in 1.8.0) no longer exist and are deleted automatically when found. A Port or X10Devices entry that still holds a value is left alone, and a banner tells you it is ignored, so you can clear or delete it yourself.</p>')
        # Additional node classes (ocelot_nodes) -- construct and self.poly.addNode() them from discover()/start() once their real addresses/names are known (run candidate names/addresses through self.poly.getValidName()/getValidAddress() first).
        self.poly.subscribe(self.poly.START, self.__start, address)
        self.poly.subscribe(self.poly.STOP, self.__stop)
        self.poly.subscribe(self.poly.POLL, self.__poll)
        self.poly.subscribe(self.poly.CONFIG, self.__configHandler)
        self.poly.subscribe(self.poly.CONFIGDONE, self.__configDoneHandler)
        self.poly.subscribe(self.poly.CUSTOMPARAMS, self.parameterHandler)
        self.poly.subscribe(self.poly.CUSTOMNS, self.__customNSHandler)
        self.poly.subscribe(self.poly.CUSTOMDATA, self.__customDataHandler)
        self.poly.subscribe(self.poly.ADDNODEDONE, self.__addNodeDoneHandler)
        self.poly.subscribe(self.poly.DELNODEDONE, self.__removeNodeDoneHandler)
        self.poly.subscribe(self.poly.DISCOVER, self.discover)
        self.poly.subscribe(self.poly.BONJOUR, self.__bonjourHandler)
        self.poly.addNode(self, conn_status='ST')

    def __start(self):
        LOGGER.info("%s: start", self.name)
        try:
            if not self.configDoneAlready:
                with self.configDone:
                    if not self.configDone.wait(timeout=10):
                        LOGGER.error("%s: timed out waiting for configDone", self.name)
                        return
            self.start()
        except Exception as ex:
            LOGGER.error("%s: start failed: %s", self.name, ex)

    def __stop(self):
        LOGGER.info("%s: stop", self.name)
        self.stop()

    def __poll(self, polltype):
        if polltype == "shortPoll":
            self.shortPoll()
        elif polltype == "longPoll":
            self.longPoll()

    def __configHandler(self, config):
        self.processConfig(config)

    def __configDoneHandler(self):
        LOGGER.info("%s: config done", self.name)
        with self.configDone:
            self.configDoneAlready = True
            self.configDone.notifyAll()

    def __addNodeDoneHandler(self, data):
        LOGGER.debug("%s: add node done: %s", self.name, data)

    def __removeNodeDoneHandler(self, data):
        LOGGER.debug("%s: remove node done: %s", self.name, data)

    def __customNSHandler(self, key, data):
        self.customParamHandler(key, data)

    def __customDataHandler(self, data):
        LOGGER.debug("%s: custom data: %s", self.name, data)

    def __bonjourHandler(self, response):
        LOGGER.debug("%s: bonjour: %s", self.name, response)

    # --- developer-authored overrides (edit freely; regeneration preserves them) ---

    def start(self):
        import ocelot_ctl
        ocelot_ctl.start(self)

    def stop(self):
        import ocelot_ctl
        ocelot_ctl.stop(self)

    def discover(self, *args, **kwargs):
        import ocelot_ctl
        ocelot_ctl.discover(self)

    def shortPoll(self, *args, **kwargs):
        import ocelot_ctl
        ocelot_ctl.short_poll(self)

    def longPoll(self, *args, **kwargs):
        import ocelot_ctl
        ocelot_ctl.long_poll(self)

    def processConfig(self, *args, **kwargs):
        pass

    def parameterHandler(self, params):
        import ocelot_ctl
        ocelot_ctl.set_params(self, params)

    def customParamHandler(self, *args, **kwargs):
        pass

    def query(self, *args, **kwargs):
        import ocelot_ctl
        ocelot_ctl.query(self)

    def rescan(self, *args, **kwargs):
        import ocelot_ctl
        ocelot_ctl.rescan(self)

    def delmodules(self, *args, **kwargs):
        import ocelot_ctl
        ocelot_ctl.delete_modules(self)

    # --- command dispatch (profile cmds.accepts; see udi_interface.Node.runCmd) ---
    commands = {'QUERY': query, 'RESCAN': rescan, 'DELMODULES': delmodules}
